function Page({path,current,cases,setCases,changeCase,query,setQuery,setNotice,navigate}){switch(path){case'/cases':return <CasesPage cases={cases} changeCase={changeCase} query={query} setQuery={setQuery} setNotice={setNotice}/>;case'/documents':return <Documents setNotice={setNotice} current={current}/>;case'/summary':return <Summary c={current}/>;case'/timeline':return <Timeline current={current} navigate={navigate} setNotice={setNotice}/>;case'/audit':return <Audit current={current} setNotice={setNotice} navigate={navigate}/>;case'/preventability':return <Preventability current={current} setNotice={setNotice}/>;case'/recommendations':return <Recommendations current={current} setNotice={setNotice}/>;case'/review':return <Review current={current} setNotice={setNotice}/>;case'/analytics':return <Analytics/>;case'/protocols':return <Protocols current={current} setNotice={setNotice}/>;case'/counterfactual':return <Counterfactual/>;case'/assistant':return <Assistant current={current}/>;case'/settings':return <Settings setNotice={setNotice}/>;default:return <Overview current={current} cases={cases} setNotice={setNotice} navigate={navigate}/>}}
function Heading({eyebrow,title,description,action}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action&&<div className="heading-action">{action}</div>}</div>}
