function Stat({label,value,change,icon:Icon,tone='rose'}){return <div className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={18}/></div><div className="stat-value">{value}</div><div className="stat-label">{label}</div>{change&&<div className="stat-change">{change}</div>}</div>}
